      })
      .where(and(
        eq(merchantSubscriptions.id, claimed.id),
        eq(merchantSubscriptions.billingClaimToken, prepared.claimToken),
      ));
    return { ok: false as const, reason: "declined" as const, message: failureReason };
  }

